def calculate_E(a, b, c):
    S = a + b + c
    P2 = a*b + b*c + c*a
    numerator = S * P2 + S
    denominator = 4 * a * b * c

    # Check if the division results in an integer
    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return None

triples = [
    (1, 2, 3), (1, 2, 4), (1, 2, 5), (1, 3, 4), (1, 3, 5), 
    (1, 4, 5), (2, 3, 4), (2, 3, 5), (2, 4, 5), (3, 4, 5)
]

integer_E_values = set()
results = {}

for a, b, c in triples:
    E = calculate_E(a, b, c)
    results[(a, b, c)] = E
    if E is not None:
        integer_E_values.add(E)

print(f"All results: {results}")
print(f"Distinct integer values of E found: {sorted(list(integer_E_values))}")

